You work with a data warehouse of several SQLite databases. Each database's tables, with a few example rows each:

-- database: shop
CREATE TABLE Customer (id INTEGER PRIMARY KEY, name TEXT);
/* 2 example rows from Customer:
id | name
1 | Ann
2 | Bob
*/

CREATE TABLE orders (oid INTEGER PRIMARY KEY, cid INTEGER, total REAL);
/* 2 example rows from orders:
oid | cid | total
10 | 1 | 9.5
11 | 1 | 3.0
*/

-- database: zoo
CREATE TABLE animal (id INTEGER PRIMARY KEY, kind TEXT, keeper_id INTEGER);
/* 1 example rows from animal:
id | kind | keeper_id
1 | lion | 1
*/

CREATE TABLE keeper (id INTEGER PRIMARY KEY, name TEXT);
/* 1 example rows from keeper:
id | name
1 | Kim
*/

